def lcs_length(a: str, b: str) -> int:
    if len(b) > len(a):
        a, b = b, a

    previous = [0] * (len(b) + 1)

    for char_a in a:
        current = [0]
        for j, char_b in enumerate(b, start=1):
            if char_a == char_b:
                current.append(previous[j - 1] + 1)
            else:
                current.append(max(previous[j], current[-1]))
        previous = current

    return previous[-1]
